function zxIcon(key){var m={shield:IC_SHIELD,lock:IC_LOCK,brain:IC_BRAIN,chart:IC_CHART,users:IC_USERS,phone:IC_PHONE,calendar:IC_CALENDAR,file:IC_FILE,bot:IC_BOT,target:IC_TARGET,search:IC_SEARCH,eye:IC_EYE,globe:IC_GLOBE,gear:IC_GEAR,zap:IC_ZAP,clock:IC_CLOCK,check:IC_CHECK,heart:IC_HEART,database:IC_DATABASE,layers:IC_LAYERS,link:IC_LINK,activity:IC_ACTIVITY,clipboard:IC_CLIPBOARD,mic:IC_MIC,mail:IC_MAIL,bell:IC_BELL,lightbulb:IC_LIGHTBULB,pill:IC_PILL,hospital:IC_HOSPITAL,user:IC_USER,stethoscope:IC_STETHOSCOPE,fax:IC_FAX,cloud:IC_CLOUD,refresh:IC_REFRESH,download:IC_DOWNLOAD,monitor:IC_MONITOR,chat:IC_CHAT,key:IC_KEY,megaphone:IC_MEGAPHONE,book:IC_BOOK,mappin:IC_MAPPIN};return(Object.prototype.hasOwnProperty.call(m,key)?m[key]:'').replace('<svg ','<svg aria-hidden="true" focusable="false" ');}
