function renderChip(text,tone,opts){opts=opts||{};var t=['brand','success','warning','danger','sample'].indexOf(tone)>-1?' zynix-chip--'+tone:'';if(!text&&tone==='sample')text='Sample data';var extra=zxCls(opts.className);if(opts.href)return'<a class="zynix-chip'+t+' zynix-chip--link'+extra+'" href="'+zxAttr(opts.href)+'">'+text+'</a>';return'<span class="zynix-chip'+t+extra+'">'+text+'</span>';}
function renderBadge(key,opts){opts=opts||{};if(!Object.prototype.hasOwnProperty.call(SITE_FACTS.compliance,key))return'';var inner=zxIcon({soc2:'shield',hipaa:'lock',hitrust:'clock'}[key])+'<span>'+SITE_FACTS.compliance[key].badge+'</span>';var tag=opts.tag||'li';if(opts.href){var a='<a class="zynix-badge" href="'+zxAttr(opts.href)+'">'+inner+'</a>';return tag==='li'?'<li>'+a+'</li>':a;}
return'<'+tag+' class="zynix-badge">'+inner+'</'+tag+'>';}
